import { POST_TYPES } from '../actions/postAction'
import { EditData, DeleteData } from '../actions/globalTypes'

// --- MOCK DATA START ---

const mockUserAlex = {
    _id: 'user_alex_123',
    avatar: 'https://placehold.co/150x150/E8D4A2/492504?text=A',
    username: 'alex_tech',
    fullname: 'Alex Doe'
};

const mockUserBella = {
    _id: 'user_bella_456',
    avatar: 'https://placehold.co/150x150/A2D4E8/042F49?text=B',
    username: 'bella_captures',
    fullname: 'Bella Smith'
};

const mockUserCharlie = {
    _id: 'user_charlie_789',
    avatar: 'https://placehold.co/150x150/D4A2E8/2E0449?text=C',
    username: 'charlie_eats',
    fullname: 'Charlie Brown'
};

const mockPosts = [
    {
        _id: 'post_1',
        content: 'Just got the new "InnovateBook Pro"! The performance is absolutely insane. Editing 4K video feels like a breeze. 💻✨ #Tech #NewLaptop',
        images: [{ url: 'https://placehold.co/600x400/CCCCCC/FFFFFF?text=InnovateBook+Pro' }],
        likes: [mockUserBella],
        comments: [
            {
                _id: 'comment_1_1',
                user: mockUserBella,
                content: 'Wow, that looks so sleek!',
                createdAt: new Date(Date.now() - 1000 * 60 * 5).toISOString() // 5 minutes ago
            }
        ],
        user: mockUserAlex,
        createdAt: new Date(Date.now() - 1000 * 60 * 10).toISOString() // 10 minutes ago
    },
    {
        _id: 'post_2',
        content: 'Caught this incredible sunset during my evening walk. Sometimes nature is the best artist. 🌅🧡 #Photography #SunsetLover',
        images: [{ url: 'https://placehold.co/600x400/FFA07A/FFFFFF?text=Sunset+View' }],
        likes: [mockUserAlex, mockUserCharlie],
        comments: [],
        user: mockUserBella,
        createdAt: new Date(Date.now() - 1000 * 60 * 60 * 2).toISOString() // 2 hours ago
    },
    {
        _id: 'post_3',
        content: 'Homemade pasta night! There is nothing better than fresh basil and a rich tomato sauce. 🍝😋 #Foodie #Pasta #Homemade',
        images: [{ url: 'https://placehold.co/600x400/90EE90/FFFFFF?text=Homemade+Pasta' }],
        likes: [],
        comments: [
             {
                _id: 'comment_3_1',
                user: mockUserAlex,
                content: 'That looks delicious! Recipe?',
                createdAt: new Date(Date.now() - 1000 * 60 * 30).toISOString() // 30 minutes ago
            },
            {
                _id: 'comment_3_2',
                user: mockUserBella,
                content: 'I need to try this!',
                createdAt: new Date(Date.now() - 1000 * 60 * 25).toISOString() // 25 minutes ago
            }
        ],
        user: mockUserCharlie,
        createdAt: new Date(Date.now() - 1000 * 60 * 60 * 5).toISOString() // 5 hours ago
    }
];

// --- MOCK DATA END ---


const initialState = {
    loading: false,
    posts: mockPosts, // Use the mock data here
    result: mockPosts.length, // Set the result count
    page: 2
}

const postReducer = (state = initialState, action) => {
    switch (action.type){
        case POST_TYPES.CREATE_POST:
            return {
                ...state,
                posts: [action.payload, ...state.posts]
            };
        case POST_TYPES.LOADING_POST:
            return {
                ...state,
                loading: action.payload
            };
        case POST_TYPES.GET_POSTS:
            return {
                ...state,
                posts: action.payload.posts,
                result: action.payload.result,
                page: action.payload.page
            };
        case POST_TYPES.UPDATE_POST:
            return {
                ...state,
                posts: EditData(state.posts, action.payload._id, action.payload)
            };
        case POST_TYPES.DELETE_POST:
            return {
                ...state,
                posts: DeleteData(state.posts, action.payload._id)
            };
        default:
            return state;
    }
}

export default postReducer;
